    customerId: 'C-001',
    number: 'INV-2026-0001',
    issueDate: '2026-10-01',
    dueDate: '2026-10-31',
    status: 'partially_paid',
    payments: [{ amount: 50000, date: '2026-10-05' }],
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 0 },
    ],
  };
  const result = createCreditNote(invoice, { amount: 25000, reason: 'Adjustment', date: '2026-10-10' }, []);
