  assert.equal(result.ok, true);
  assert.equal(result.value.amount, 102850);
});

test('createCreditNote rejects invalid date format', () => {
  const invoice = {
    customerId: 'C-001',
    number: 'INV-2026-0001',
    issueDate: '2026-10-01',
    dueDate: '2026-10-31',
