test('nextCreditNoteNumber returns CN-0001 for empty list', () => {
  const number = nextCreditNoteNumber([], '2026-10-01');
  assert.equal(number, 'CN-2026-0001');
});

test('nextCreditNoteNumber increments counter', () => {
  const numbers = ['CN-2026-0001'];
  const number = nextCreditNoteNumber(numbers, '2026-10-15');
  assert.equal(number, 'CN-2026-0002');
});

test('nextCreditNoteNumber handles multiple existing credit notes', () => {
  const numbers = ['CN-2026-0001', 'CN-2026-0002', 'CN-2026-0003'];
  const number = nextCreditNoteNumber(numbers, '2026-10-15');
  assert.equal(number, 'CN-2026-0004');
});

test('nextCreditNoteNumber resets counter for new year', () => {
  const numbers = ['CN-2026-0001', 'CN-2026-0002', 'CN-2025-0005'];
  const number = nextCreditNoteNumber(numbers, '2027-01-15');
  assert.equal(number, 'CN-2027-0001');
});

test('nextCreditNoteNumber ignores invoice numbers', () => {
  const numbers = ['INV-2026-0001', 'INV-2026-0002', 'CN-2026-0001'];
  const number = nextCreditNoteNumber(numbers, '2026-10-15');
  assert.equal(number, 'CN-2026-0002');
});

test('nextCreditNoteNumber handles mixed invoice and credit note numbers', () => {
  const numbers = ['INV-2026-0001', 'CN-2026-0001', 'INV-2026-0002', 'CN-2026-0002'];
  const number = nextCreditNoteNumber(numbers, '2026-10-15');
  assert.equal(number, 'CN-2026-0003');
});

test('nextCreditNoteNumber ignores invalid credit note numbers', () => {
  const numbers = ['CN-2026-invalid', 'CN-2026-0001'];
  const number = nextCreditNoteNumber(numbers, '2026-10-15');
  assert.equal(number, 'CN-2026-0002');
});

test('nextCreditNoteNumber zero-pads counter to 4 digits', () => {
  const numbers = Array.from({ length: 99 }, (_, i) => `CN-2026-${String(i + 1).padStart(4, '0')}`);
  const number = nextCreditNoteNumber(numbers, '2026-10-15');
  assert.equal(number, 'CN-2026-0100');
});

test('createCreditNote with discount on invoice', () => {
  const invoice = {
    customerId: 'C-001',
    number: 'INV-2026-0001',
    issueDate: '2026-10-01',
    dueDate: '2026-10-31',
    status: 'issued',
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 5 },
    ],
  };
  const result = createCreditNote(invoice, { amount: 50000, reason: 'Partial refund', date: '2026-10-10' }, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.amount, 50000);
});

