  const invoice = {
    customerId: 'C-001',
    number: 'INV-2026-0001',
    issueDate: '2026-10-01',
    dueDate: '2026-10-31',
    status: 'issued',
    voucher: { code: 'PROMO10', amount: 10000 },
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 0 },
    ],
  };
  const result = createCreditNote(invoice, { amount: 90000, reason: 'Partial refund', date: '2026-10-10' }, []);
  assert.equal(result.ok, true);
});

test('createCreditNote respects invoice total after voucher', () => {
  const invoice = {
    customerId: 'C-001',
    number: 'INV-2026-0001',
    issueDate: '2026-10-01',
    dueDate: '2026-10-31',
    status: 'issued',
    voucher: { code: 'PROMO10', amount: 10000 },
    lines: [
      { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 0 },
    ],
  };
  assert.deepEqual(createCreditNote(invoice, { amount: 102850, reason: 'Over-limit', date: '2026-10-10' }, []), { ok: false, error: 'CREDIT_TOO_HIGH' });
});

test('createCreditNote includes all fields', () => {
  const invoice = {
    customerId: 'C-002',
    number: 'INV-2026-0005',
    issueDate: '2026-10-01',
    dueDate: '2026-10-31',
    status: 'issued',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, unitPrice: 9500, name: 'Development (hour)', vatRate: 21, discountPercent: 0 },
    ],
  };
  const result = createCreditNote(invoice, { amount: 30000, reason: 'Service issue', date: '2026-10-15' }, ['CN-2026-0001']);
  assert.equal(result.ok, true);
  const cn = result.value;
  assert.equal(cn.number, 'CN-2026-0002');
  assert.equal(cn.invoiceNumber, 'INV-2026-0005');
  assert.equal(cn.customerId, 'C-002');
  assert.equal(cn.amount, 30000);
  assert.equal(cn.reason, 'Service issue');
  assert.equal(cn.date, '2026-10-15');
});

